agent_base_units.command:
cd /app && cat > /tmp/json-schema-scratch.ts <<'EOF'
import { jsonSchemaToType } from "/app/ark/json-schema/index.ts"

function test(name: string, fn: () => void) {
	try { fn() } catch (e) { console.log(`--- ${name} ERR:`, (e as Error).message) }
}

test("array of refs recursion", () => {
	const t = jsonSchemaToType({ $defs: { node: { type: "object", properties: { value: { type: "string" }, children: { type: "array", items: { $ref: "#/$defs/node" } } }, required: ["value"] } }, $ref: "#/$defs/node" })
	console.log("array refs", t.expression)
	console.log("leaf", t.allows({value:"x"}))
	console.log("nested", t.allows({value:"x", children:[{value:"y"},{value:"z", children:[{value:"w"}]}]}))
	console.log("bad child", t.allows({value:"x", children:[{value:1}]}))
})

test("allOf recursion", () => {
	const t = jsonSchemaToType({ $defs: { base: { type: "object", properties: { a: { type: "string" } } }, node: { allOf: [ { $ref: "#/$defs/base" }, { type: "object", properties: { child: { $ref: "#/$defs/node" } } } ] } }, $ref: "#/$defs/node" })
	console.log("allOf recursion", t.expression)
	console.log("ok", t.allows({a:"x"}))
	console.log("nested", t.allows({a:"x", child:{a:"y"}}))
})

test("non-raw enum def", () => {
	const t = jsonSchemaToType({ $defs: { e: { enum: [{a:1}, [1,2]] } }, type: "object", properties: { x: { $ref: "#/$defs/e" } } })
	console.log("enum def", t.expression, t.allows({x:{a:1}}), t.allows({x:{a:2}}), t.allows({x:[1,2]}))
})

test("def ref to non-raw def", () => {
	const t = jsonSchemaToType({ $defs: { e: { enum: [1,2] }, obj: { type: "object", properties: { x: { $ref: "#/$defs/e" } }, required: ["x"] } }, $ref: "#/$defs/obj" })
	console.log("def ref to enum", t.expression, t.allows({x:1}), t.allows({x:3}))
})

test("anyOf alias double check", () => {
	const t = jsonSchemaToType({ $defs: { leaf: { type: "string" }, node: { anyOf: [ { $ref: "#/$defs/leaf" }, { type: "number" } ] } }, $ref: "#/$defs/node" })
	console.log("anyOf alias", t.expression, t.allows("x"), t.allows(1), t.allows(true))
})

test("ref in then", () => {
	const t = jsonSchemaToType({ $defs: { s: { type: "string", minLength: 3 } }, if: { type: "string" }, then: { $ref: "#/$defs/s" } })
	console.log("ref in then", t.allows("ab"), t.allows("abc"), t.allows(5))
})
EOF
timeout 60 pnpm ts /tmp/json-schema-scratch.ts 2>&1 | tail -40
